const state={mode:"chat",sessionId:null,pendingRiskPrompt:null,running:false,explorerPath:".",statuses:[]};
const $=id=>document.getElementById(id);
function log(line){const el=$("terminal-log");const ts=new Date().toISOString().slice(11,19);el.textContent+=`[${ts}] ${line}\n`;el.scrollTop=el.scrollHeight;}
function setRunStatus(text,cls){const el=$("run-status");el.textContent=text;el.className=`run-status ${cls||""}`;}
async function api(path,opts={}){const res=await fetch(path,{headers:{"Content-Type":"application/json",...(opts.headers||{})},...opts});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);return data;}
function appendMessage(role,content,extra){const box=$("messages");const div=document.createElement("div");div.className=`msg ${role}${extra?" "+extra:""}`;div.textContent=content;box.appendChild(div);box.scrollTop=box.scrollHeight;}
function clearMessages(){$("messages").innerHTML="";}
function escapeHtml(s){return String(s).replace(/&/g,"&").replace(/</g,"<").replace(/>/g,">");}
function renderModes(){const modes=[{id:"chat",name:"Chat",sub:"Shared provider / offline stub"},{id:"work",name:"Work",sub:"OpenClaw CLI"},{id:"code",name:"Code",sub:"OpenCode CLI"},{id:"agent",name:"Agent",sub:"Hermes Agent CLI"}];const root=$("mode-switcher");root.innerHTML="";for(const m of modes){const btn=document.createElement("button");btn.type="button";btn.className=`mode-btn${state.mode===m.id?" active":""}`;btn.innerHTML=`<strong>${m.name}</strong><span class="sub">${m.sub}</span>`;btn.onclick=()=>selectMode(m.id);root.appendChild(btn);}const badge=$("current-mode-badge");badge.textContent=state.mode;badge.className=`badge ${state.mode}`;}
function selectMode(mode){if(state.running)return;state.mode=mode;state.sessionId=null;renderModes();clearMessages();appendMessage("system",`Switched to ${mode.toUpperCase()}. Uses real backend.`);updateProviderHint();log(`Mode → ${mode}`);}
function updateProviderHint(){const chat=state.statuses.find(s=>s.mode==="chat");const cur=state.statuses.find(s=>s.mode===state.mode);const el=$("chat-provider-hint");if(state.mode==="chat"){if(chat?.transport==="http"){el.textContent="Chat: live provider";el.style.color="var(--good)";}else{el.textContent="Chat: OFFLINE STUB (set OPENAI_API_KEY or OPENROUTER_API_KEY)";el.style.color="var(--warn)";}}else if(cur&&!cur.available){el.textContent=`${state.mode}: backend not installed`;el.style.color="var(--bad)";}else if(cur?.available){el.textContent=`${state.mode}: ${cur.version||"ready"}`;el.style.color="var(--good)";}else el.textContent="";}
function renderBackends(statuses){state.statuses=statuses;const root=$("backend-status");root.innerHTML="";for(const s of statuses){const row=document.createElement("div");row.className="backend-row";row.innerHTML=`<span class="dot ${s.available?"ok":"bad"}"></span><div><strong>${s.mode}</strong><div class="msg">${escapeHtml(s.message||"")}</div></div>`;root.appendChild(row);}updateProviderHint();}
async function refreshStatus(){try{const data=await api("/api/status");renderBackends(data.statuses||[]);$("workspace-label").textContent=data.workspace||"";log("Backend status refreshed");}catch(err){log(`Status error: ${err.message}`);}}
async function refreshSessions(){try{const data=await api("/api/sessions");const root=$("session-list");root.innerHTML="";for(const s of data.sessions||[]){const btn=document.createElement("button");btn.type="button";btn.className=`session-item${state.sessionId===s.id?" active":""}`;btn.innerHTML=`<div>${escapeHtml(s.title||s.id)}</div><div class="meta">${s.mode} · ${s.messageCount} msgs</div>`;btn.onclick=()=>loadSession(s.id);root.appendChild(btn);}}catch(err){log(`Sessions error: ${err.message}`);}}
async function loadSession(id){try{const store=await api(`/api/sessions/${id}`);state.sessionId=store.session.id;state.mode=store.session.mode;renderModes();clearMessages();for(const m of store.messages||[])appendMessage(m.role==="user"?"user":m.role==="assistant"?"assistant":"system",m.content);updateProviderHint();await refreshSessions();log(`Loaded session ${id}`);}catch(err){appendMessage("system",err.message,"error");}}
async function refreshFiles(path=state.explorerPath){try{const data=await api(`/api/workspace?path=${encodeURIComponent(path)}`);state.explorerPath=data.path||path;$("file-path").textContent=data.path||".";const root=$("file-explorer");root.innerHTML="";if(data.path&&data.path!=="."){const up=document.createElement("button");up.type="button";up.className="file-item";up.textContent="📁 ..";up.onclick=()=>{const parts=data.path.split("/").filter(Boolean);parts.pop();refreshFiles(parts.length?parts.join("/"):".");};root.appendChild(up);}for(const item of data.items||[]){const btn=document.createElement("button");btn.type="button";btn.className="file-item";btn.textContent=`${item.type==="dir"?"📁":"📄"} ${item.name}`;btn.onclick=()=>{if(item.type==="dir")refreshFiles(item.path);else openFile(item.path);};root.appendChild(btn);}}catch(err){log(`Explorer error: ${err.message}`);}}
async function openFile(path){try{const file=await api(`/api/workspace/file?path=${encodeURIComponent(path)}`);$("file-preview").classList.remove("hidden");$("preview-title").textContent=file.path;$("preview-content").textContent=file.content;log(`Opened ${path}`);}catch(err){log(`Open file failed: ${err.message}`);}}
function hideApproval(){$("approval-banner").classList.add("hidden");state.pendingRiskPrompt=null;}
async function sendPrompt(confirmRisk=false){const input=$("prompt-input");const prompt=(state.pendingRiskPrompt||input.value).trim();if(!prompt||state.running)return;state.running=true;$("btn-send").disabled=true;setRunStatus("running…","running");log(`RUN mode=${state.mode}`);if(!confirmRisk){appendMessage("user",prompt);input.value="";}try{const result=await api("/api/run",{method:"POST",body:JSON.stringify({mode:state.mode,prompt,sessionId:state.sessionId,confirmRisk})});if(result.status==="awaiting_approval"&&result.requiresConfirmation){state.pendingRiskPrompt=prompt;$("approval-detail").textContent="Risky patterns: "+(result.riskPatterns||[]).join(", ");$("approval-banner").classList.remove("hidden");setRunStatus("awaiting approval","error");return;}hideApproval();if(result.backendMeta?.sessionId)state.sessionId=result.backendMeta.sessionId;if(result.status==="completed"){appendMessage("assistant",result.output||"(empty)");setRunStatus("completed","ok");}else{appendMessage("system",result.error||"Run failed","error");setRunStatus("failed","error");log(`Failed: ${result.error}`);}await refreshSessions();}catch(err){appendMessage("system",err.message,"error");setRunStatus("error","error");}finally{state.running=false;$("btn-send").disabled=false;}}
function wireEvents(){$("btn-refresh-status").onclick=refreshStatus;$("btn-refresh-files").onclick=()=>refreshFiles(state.explorerPath);$("btn-clear-log").onclick=()=>{$("terminal-log").textContent="";};$("btn-close-preview").onclick=()=>$("file-preview").classList.add("hidden");$("btn-new-session").onclick=()=>{state.sessionId=null;clearMessages();appendMessage("system",`New ${state.mode} session.`);refreshSessions();};$("prompt-form").onsubmit=e=>{e.preventDefault();sendPrompt(false);};$("btn-approve").onclick=()=>sendPrompt(true);$("btn-cancel-risk").onclick=()=>{hideApproval();setRunStatus("cancelled","");};$("prompt-input").addEventListener("keydown",e=>{if(e.key==="Enter"&&(e.metaKey||e.ctrlKey)){e.preventDefault();sendPrompt(false);}});}
async function boot(){renderModes();wireEvents();appendMessage("system","Web IDE connected to IdeEngine.\nChat / Work (OpenClaw) / Code (OpenCode) / Agent (Hermes).");await refreshStatus();await refreshSessions();await refreshFiles(".");log("GUI ready");}
boot();
